import {cpiWindowData} from './planning-cpi-window-data.js';
export const cpiWindowDefinitions={cpiWindowCash:{title:'Keep the CPI snapshot fixed while exploring a separate monthly-price assumption',fields:[
 ['windowBudget','Current reference-month basket cost (CAD)',3000,0,20000,100],
 ['windowMonthlyRate','Independent assumed price change each future month (%)',.4,-1,2,.05]
 ]}};
export function cpiWindowLedger(p){
 const log=Math.log1p(p.windowMonthlyRate/100),rows=Array.from({length:13},(_,month)=>({x:month,value:p.windowBudget*Math.exp(log*month)})),spending=rows.slice(1).reduce((s,r)=>s+r.value,0),baseline=12*p.windowBudget;
 return {rows,spending,baseline,increment:spending-baseline,ending:rows.at(-1).value,priceChange:Math.expm1(log*12)};
}
export function cpiWindowResult(kind,input){
 if(kind!=='cpiWindowCash')throw Error('Unknown CPI measurement-window view');
 const s=cpiWindowData,r=cpiWindowLedger(input),year=s.publishedRates[0];
 return {metrics:[['Official September 2026 change · 12-month NSA',year.value/100,'percent',year.original+'%'],['Hypothetical 12-month price change',r.priceChange,'percent'],['Sum of twelve hypothetical future monthly bills',r.spending,'money']],
 note:'Fixed Canada all-items CPI snapshot released 19 October and reviewed 25 October 2026. The first two figures retain official reference months, seasonal-adjustment definitions and one-decimal source precision. The August 2026 SA observation is flagged revised. Month-start source dates label monthly periods. The last two figures are independent original scenarios with constant basket quantities, an entered reference-month cost and the same assumed price change before each of twelve future monthly bills. Month zero is a reference cost, not an extra paid bill. Source statistics stay unchanged when either input changes. No actual CPI forecast, personalized inflation estimate, income, tax, saving return, borrowing or welfare/cost-of-living calculation is supplied.',
 charts:[
 {id:'cpi-window-index-history',type:'line',unit:'decimal',unitLabel:'Index, 2002=100 · Canada all-items; focused vertical axis 160–172',tableUnit:'Index (2002=100), original one-decimal precision; R = revised',source:'https://www.bankofcanada.ca/stats/cpi',sourceLabel:'Bank of Canada · Statistics Canada monthly CPI series',title:'Compare the same reference months with and without seasonal adjustment',yMin:160,yMax:172,xMin:0,xLabel:'Reference month',xTicks:[{value:0,label:'Sep 25'},{value:6,label:'Mar 26'},{value:12,label:'Sep 26'}],series:[{name:'Not seasonally adjusted',rows:s.rows.map((x,k)=>({x:k,label:x.reference+(x.nsa.flags.r?' (R)':''),value:x.nsa.value}))},{name:'Seasonally adjusted',dash:true,rows:s.rows.map((x,k)=>({x:k,label:x.reference+(x.sa.flags.r?' (R)':''),value:x.sa.value}))}],note:'The vertical axis focuses on 160–172 and does not begin at zero. Both series are indices on the same 2002=100 base, not CAD prices. Seasonal adjustment changes the time-series treatment, not the measurement currency. The August 2026 adjusted value 169.4 carries the publisher’s revision flag R in the table. All values belong to the retained 25 October retrieval vintage.'},
 {id:'cpi-window-published-changes',type:'bar',unit:'decimal',unitLabel:'Published percentage change (%) · source precision one decimal',tableUnit:'Percent; one decimal as published, not a recomputed high-precision rate',axisTicks:2,source:'https://www150.statcan.gc.ca/n1/daily-quotidien/261019/dq261019a-eng.htm',sourceLabel:'Statistics Canada · September 2026 CPI release',title:'Three published rates answer three labelled measurement questions',rows:s.publishedRates.map(x=>({label:x.label,value:x.value})),note:'NSA means not seasonally adjusted; SA means seasonally adjusted. All three refer to September 2026 but use different windows or adjustment: the 12-month unadjusted change is 3.1%, the one-month unadjusted change 0.1%, and the one-month adjusted change 0.4%. The bars are separate comparisons, not components to add or a forecast. Ratios recomputed from rounded published index levels need not equal a high-precision underlying official calculation.'},
 {id:'cpi-window-hypothetical-cost',type:'line',unit:'money',unitLabel:'CAD hypothetical cost of unchanged basket quantities',title:'Repeating one monthly assumption creates an authored price path',xMin:0,xLabel:'Future month; 0 = current reference',series:[{name:'Basket cost after assumed monthly changes',rows:r.rows}],note:'This curve uses only the two independent inputs. Each future month’s cost is reference cost × (1 + entered monthly rate)^month. The first price change occurs before month one’s bill. Holding one rate constant for twelve months is a counterfactual scenario, not a continuation of the official index history or an estimate of next year’s CPI.'},
 {id:'cpi-window-first-year-bills',type:'waterfall',unit:'money',unitLabel:'CAD sum of twelve hypothetical future bills; months 1–12',title:'Add the twelve bills rather than charging the final month’s cost all year',rows:[{label:'Twelve reference-cost bills',value:r.baseline},{label:'Monthly price-path difference',value:r.increment}],totalLabel:'Total of twelve future bills',note:'The first step is twelve times the unchanged reference-month cost. The second is the sum of each future bill’s difference from that reference, with negative differences retained for assumed deflation. The endpoint sums months one through twelve. Twelve times the final bill would instead assume that the final price applied in every month; month zero is not added to either calculation.'}
 ]};
}
